583	import type { AppRouter } from '@repo/api';
584	import { TRPCClientError, type TRPCLink } from '@trpc/client';
585	import { observable } from '@trpc/server/observable';
586	import type { RouterInputs, RouterOutputs } from './trpc';
587	
588	type ProcedurePath = {
589	  [Router in keyof RouterInputs & string]: `${Router}.${keyof RouterInputs[Router] & string}`;
590	}[keyof RouterInputs & string];
591	
592	type Lookup<Tree, Path> = Path extends `${infer Router}.${infer Procedure}`
593	  ? Router extends keyof Tree
594	    ? Procedure extends keyof Tree[Router]
595	      ? Tree[Router][Procedure]
596	      : never
597	    : never
598	  : never;
599	
600	/** A fake answer per procedure path, such as `'greeting.greet'`, typed by the router. */
601	export type TestApiHandlers = {
602	  readonly [Path in ProcedurePath]?: (
603	    input: Lookup<RouterInputs, Path>,
604	  ) => Lookup<RouterOutputs, Path> | Promise<Lookup<RouterOutputs, Path>>;
605	};
606	
607	/** A tRPC link that answers each call from `handlers` instead of the network. */
608	export function handlerLink(handlers: TestApiHandlers): TRPCLink<AppRouter> {
609	  return () =>
610	    ({ op }) =>
611	      observable((observer) => {
612	        const handler = handlers[op.path as ProcedurePath] as
613	          | ((input: unknown) => unknown)
614	          | undefined;
615	        Promise.resolve(op.input)
616	          .then((input) => {
617	            if (!handler) {
618	              throw new Error(`TestApiProvider has no handler for ${op.path}`);
619	            }
620	            return handler(input);
621	          })
622	          .then(
623	            (data) => {
624	              observer.next({ result: { type: 'data', data } });
625	              observer.complete();
626	            },
627	            (cause: Error) => observer.error(TRPCClientError.from(cause)),
628	          );
629	      });
630	}
