1017	type Greeting = RouterOutputs['greeting']['greet'];
1018	
1019	export type GreetingState =
1020	  | { readonly status: 'idle' }
1021	  | { readonly status: 'loading' }
1022	  | { readonly status: 'success'; readonly message: Greeting['message'] }
1023	  | { readonly status: 'error' };
