1025	/** The greeting for the last submitted name, fetched through the api. */
1026	export function useGreeting() {
1027	  const [name, setName] = useState<GreetInput['name'] | null>(null);
1028	  const trpc = useTrpc();
1029	  const query = useQuery(trpc.greeting.greet.queryOptions(name === null ? skipToken : { name }));
1030	
1031	  function requestGreeting(nextName: GreetInput['name']) {
1032	    setName(nextName);
1033	    if (nextName === name) {
1034	      void query.refetch();
1035	    }
1036	  }
1037	
1038	  let greeting: GreetingState;
1039	  if (name === null) {
1040	    greeting = { status: 'idle' };
1041	  } else if (query.isFetching) {
1042	    greeting = { status: 'loading' };
1043	  } else if (query.isError) {
1044	    greeting = { status: 'error' };
1045	  } else if (query.data) {
1046	    greeting = { status: 'success', message: query.data.message };
1047	  } else {
1048	    greeting = { status: 'loading' };
1049	  }
